mapper.sql:
from sys_outbox o
where o.created_at >= #{q.from} and o.created_at < #{q.to}
and o.topic = #{q.topic}
and o.status = #{q.status}
and o.biz_key like #{q.bizLike} escape '\'

mapper.update:
update sys_outbox
   set status = 'CLOSED_MANUAL', closed_at = now(), closed_by = #{by}, close_reason = #{reason}
 where outbox_id = #{outboxId} and status = 'FAIL' and close_apr_id is null

update sys_outbox
   set close_apr_id = #{aprId}, close_reason = #{reason}, closed_by = #{by}
 where outbox_id = #{outboxId} and status = 'FAIL' and close_apr_id is null
